inal)", "regla": "ml", "insumo": "perfil-l-aluminio", "cantidad": "2", "metros": "(si(P >= 120, si(L < 300, 80, 90), si(L <= 120, L * 38.5 / 120, si(L < 160, 38.5 + (L - 120) * 23.5 / 40, si(L < 190, 62 + (L - 160) * 18 / 30, si(L < 250, 80, 90)))))) / 100"}, {"id": "perfil_corta", "nombre": "Perfiles L (bases transversales)", "regla": "ml", "insumo": "perfil-l-aluminio", "cantidad": "2 * si(P >= 120, 2, 1)", "metros": "(si(P - 10 < 90, P - 10, 90)) / 100"}]}'::jsonb, 'Carga inicial con los planos de las bases');
select pg_temp.publicar_receta('Mesa Aire Ratona Rectangular', '{"orden": ["L", "P", "H", "terminacion", "color", "espesor"], "entradas": {"L": {"tipo": "medida", "nombre": "Largo", "min": 80, "max": 160, "def": 100}, "P": {"tipo": "medida", "nombre": "Profundidad", "min": 40, "max": 90, "def": 70}, "H": {"tipo": "medida", "nombre": "Alto", "def": 40}, "terminacion": {"tipo": "opcion", "nombre": "Tapa", "permitidos": ["Madera clara", "Madera negra mate", "Madera oscura", "Madera roble", "Melamina lisa de color"], "def": "Madera clara"}, "color": {"tipo": "opcion", "nombre": "Vidrio", "atributo": "color", "def": "incoloro"}, "espesor": {"tipo": "opcion", "nombre": "Espesor", "permitidos": ["5+5", "10"], "def": "5+5"}}, "lineas": [{"id": "tapa", "nombre": "Tapa de melamina", "regla": "tabla", "insumo": "tapa-melamina-rectangular", "referencia": "L + P"}, {"id": "base_larga", "nombre": "Base longitudinal", "regla": "m2", "insumoFormula": "si(espesor == ''10'' && en(color, ''incoloro'', ''gris'', ''bronce''), ''vidrio-float'', ''vidrio-laminado'')", "variante": {"espesor": "''10''", "composicion": "''5+5''", "color": "color"}, "ancho": "redondear(L * 38.5 / 120)", "largo": "H", "nota": "Sin plano: proporcional a la base de la Aire Alta 120 × 90"}, {"id": "base_corta", "nombre": "Base transversal", "regla": "m2", "insumoFormula": "si(espesor == ''10'' && en(color, ''incoloro'', ''gris'', ''bronce''), ''vidrio-float'', ''vidrio-laminado'')", "variante": {"espesor": "''10''", "composicion": "''5+5''", "color": "color"}, "cantidad": "1", "ancho": "redondear(P * 80 / 90)", "largo": "H", "nota": "Sin plano: proporcional a la base de la Aire Alta 120 × 90"}, {"id": "ajuste", "nombre": "Ajuste", "regla": "porcentaje", "porcentaje": "aj.ajuste_vidpro", "sobre": ["base_larga", "base_corta"], "nota": "Mesa baja: 20% sobre todos los vidrios (son solo las bases)"}, {"id": "silicona", "nombre": "Pegado con silicona", "regla": "fijo", "insumo": "silicona"}, {"id": "perfil_larga", "nombre": "Perfiles L (base longitudinal)", "regla": "ml", "insumo": "perfil-l-aluminio", "cantidad": "2", "metros": "(redondear(L * 38.5 / 120)) / 100"}, {"id": "perfil_corta", "nombre": "Perfiles L (bases transversales)", "regla": "ml", "insumo": "perfil-l-aluminio", "cantidad": "2", "metros": "(redondear(P * 80 / 90)) / 100"}]}'::jsonb, 'Sin planos: bases proporcionales a la Alta 120 × 90');
